// 2. Fit on training rows only, then predict untouched held-out X.
model, err := tabular.Fit(train)
if err != nil { panic(err) }
defer model.Close()
predicted, err := model.Predict(heldout.X)
if err != nil { panic(err) }
metrics, err := tabular.Evaluate(heldout.Y, predicted)
if err != nil { panic(err) }
fmt.Printf("Held-out MAE: %.6f\nRMSE: %.6f\nR2: %.6f\n", metrics.MAE, metrics.RMSE, metrics.R2)

// 3. Persist the versioned model, reopen it, and verify exact round-trip parity.
modelFile, err := os.Create("model.json")
if err != nil { panic(err) }
if err = model.Save(modelFile); err != nil { modelFile.Close(); panic(err) }
if err = modelFile.Close(); err != nil { panic(err) }
modelInput, err := os.Open("model.json")
if err != nil { panic(err) }
restored, err := tabular.Load(modelInput)
closeErr := modelInput.Close()
if err != nil { panic(err) }
defer restored.Close()
if closeErr != nil { panic(closeErr) }
roundtrip, err := restored.Predict(heldout.X)
if err != nil { panic(err) }
for i := range predicted {
    if math.Float64bits(predicted[i]) != math.Float64bits(roundtrip[i]) { panic("model round-trip changed prediction") }
}
output, err := os.Create("predictions.csv")
if err != nil { panic(err) }
writer := csv.NewWriter(output)
if err = writer.Write([]string{"hours", "actual_score", "predicted_score"}); err != nil { output.Close(); panic(err) }
for i, x := range heldout.X {
    row := []string{strconv.FormatFloat(x, 'g', -1, 64), strconv.FormatFloat(heldout.Y[i], 'g', -1, 64), strconv.FormatFloat(predicted[i], 'g', -1, 64)}
    if err = writer.Write(row); err != nil { output.Close(); panic(err) }
}
writer.Flush()
if err = writer.Error(); err != nil { output.Close(); panic(err) }
if err = output.Close(); err != nil { panic(err) }
if err = model.Close(); err != nil { panic(err) }
if err = restored.Close(); err != nil { panic(err) }
if _, err = restored.Predict(heldout.X); err == nil { panic("closed model unexpectedly predicts") }
fmt.Println("Saved model.json and predictions.csv; restored predictions match; both models closed.")
